import fs from 'fs';
import path from 'path';

const dir = path.join(process.env.USERPROFILE, '.dsh/storages/session_projcache/sessions');
const rows = [];
for (const f of fs.readdirSync(dir)) {
  if (!f.endsWith('.json')) continue;
  const full = path.join(dir, f);
  let j;
  try { j = JSON.parse(fs.readFileSync(full, 'utf8')); } catch { continue; }
  const r = j.record?.rows || {};
  const g = (x) => (x && x.val !== undefined ? x.val : x);
  const wd = g(r.workingDirectory);
  const wdText = typeof wd === 'string' ? wd : JSON.stringify(wd || '');
  if (!/防汛|flood/i.test(wdText)) continue;
  const title = g(r.title);
  const model = g(r.modelSelection)?.lastUsed || {};
  const tu = g(r.tokenUsage)?.totals || {};
  const ss = g(r.sessionStats) || {};
  const st = fs.statSync(full);
  rows.push({
    mtime: st.mtimeMs,
    sid: f.replace(/^session-/, '').replace(/\.json$/, ''),
    short: f.slice(8, 16),
    title: String(typeof title === 'string' ? title : (title?.text || '')).replace(/\s+/g, ' ').slice(0, 60),
    wd: wdText.replace(/\s+/g, ' ').slice(0, 120),
    model: `${model.provider || ''}/${model.model || '?'}`,
    turns: ss.turns, steps: ss.steps,
    uncached: tu.uncachedInputTokens || 0,
    cache: tu.cacheReadTokens || 0,
    out: tu.outputTokens || 0,
  });
}
rows.sort((a, b) => b.mtime - a.mtime);
for (const x of rows.slice(0, 8)) {
  const hit = x.cache + x.uncached ? Math.round(100 * x.cache / (x.cache + x.uncached)) : 0;
  console.log([new Date(x.mtime).toISOString(), x.short, x.sid, x.model, `t${x.turns}`, `s${x.steps}`, `hit${hit}%`, `unc${x.uncached}`, `cache${x.cache}`, `out${x.out}`, x.title, x.wd].join(' | '));
}
console.log('matched', rows.length);

import fs from 'fs';
import zlib from 'zlib';
import path from 'path';

const fp = process.argv[2];
function zstdAll(buf) {
  const MAGIC = Buffer.from([0x28, 0xb5, 0x2f, 0xfd]);
  const idxs = [];
  for (let i = 0; (i = buf.indexOf(MAGIC, i)) >= 0; i += 4) idxs.push(i);
  if (idxs.length <= 1) return zlib.zstdDecompressSync(buf).toString('utf8');
  let out = '';
  for (let k = 0; k < idxs.length; k++) {
    const s = idxs[k];
    const e = k + 1 < idxs.length ? idxs[k + 1] : buf.length;
    try { out += zlib.zstdDecompressSync(buf.subarray(s, e)).toString('utf8'); } catch {}
  }
  return out;
}
const text = zstdAll(fs.readFileSync(fp));
const calls = new Map();
let n = 0;
const counts = {};
for (const line of text.split('\n')) {
  if (!line.trim()) continue;
  let ev;
  try { ev = JSON.parse(line); } catch { continue; }
  const t = ev.type || '';
  const d = ev.data || {};
  if (t === 'tool/call') {
    n += 1;
    const name = d.toolName || d.name || '?';
    counts[name] = (counts[name] || 0) + 1;
    const args = d.arguments || d.args || d.input || {};
    const target = args.file_path || args.path || args.command || args.pattern || args.name || '';
    const id = d.callId || d.id || String(n);
    calls.set(id, { n, name, target: String(target).replace(/\s+/g, ' ').slice(0, 110) });
  } else if (t === 'tool/result') {
    const id = d.message?.toolCallId || d.toolCallId;
    const rec = id && calls.get(id);
    if (!rec) continue;
    const msg = JSON.stringify(d.message || d).slice(0, 400);
    rec.bad = /error|Error|INVALID|FS_|ENOENT|failed/i.test(msg);
  }
}
console.log('calls', n, JSON.stringify(counts));
for (const rec of calls.values()) {
  console.log(String(rec.n).padStart(2, '0'), rec.bad ? 'ERR' : 'ok ', rec.name, rec.target);
}

