import fs from 'fs';
import zlib from 'zlib';
const fp = process.argv[2];
function zstdAll(buf) {
  const MAGIC = Buffer.from([0x28, 0xb5, 0x2f, 0xfd]);
  const idxs = [];
  for (let i = 0; (i = buf.indexOf(MAGIC, i)) >= 0; i += 4) idxs.push(i);
  if (idxs.length <= 1) return zlib.zstdDecompressSync(buf).toString('utf8');
  let out = '';
  for (let k = 0; k < idxs.length; k++) {
    const s = idxs[k], e = k + 1 < idxs.length ? idxs[k + 1] : buf.length;
    try { out += zlib.zstdDecompressSync(buf.subarray(s, e)).toString('utf8'); } catch {}
  }
  return out;
}
function pick(args) {
  if (typeof args === 'string') { try { args = JSON.parse(args); } catch { return args.slice(0, 90); } }
  if (!args || typeof args !== 'object') return '';
  const v = args.file_path || args.path || args.pattern || args.command || args.tool || args.name || '';
  return String(v).replace(/\s+/g, ' ').slice(0, 110);
}
const text = zstdAll(fs.readFileSync(fp));
const calls = new Map();
let n = 0;
for (const line of text.split('\n')) {
  if (!line.trim()) continue;
  let ev; try { ev = JSON.parse(line); } catch { continue; }
  const d = ev.data || {};
  if (ev.type === 'tool/call') {
    n += 1;
    calls.set(d.callId, { n, name: d.name, target: pick(d.arguments), turn: d.turn, step: d.step });
  } else if (ev.type === 'tool/result' && d.message?.isError) {
    const rec = calls.get(d.message.toolCallId);
    if (rec) rec.bad = true;
  }
}
for (const rec of calls.values()) {
  console.log([rec.turn + '.' + rec.step, rec.bad ? 'ERR' : 'ok', rec.name, rec.target].join(' | '));
}
